// Minifies the loader and writes it into the web app, which serves it at /widget.js with
// the runtime API/web URLs substituted. Run after editing src/loader.js (CI checks that the
// generated file is up to date).
import { build } from "esbuild";
import { writeFileSync } from "node:fs";

const result = await build({
  entryPoints: ["src/loader.js"],
  bundle: false,
  minify: true,
  target: ["es2017"],
  write: false,
  legalComments: "none",
  banner: { js: "/* Horizon Valley widget loader */" },
});
const code = result.outputFiles[0].text.trim();
for (const placeholder of ['"__HV_API__"', '"__HV_WEB__"']) {
  if (!code.includes(placeholder)) throw new Error(`placeholder ${placeholder} lost during minification`);
}
const out = `// GENERATED by widget/build.mjs — do not edit. Source: widget/src/loader.js\nexport const WIDGET_LOADER = ${JSON.stringify(code)};\n`;
writeFileSync(new URL("../web/lib/widget-loader.generated.ts", import.meta.url), out);
console.log(`widget.js: ${code.length} bytes minified`);
